#!/usr/bin/env bash
# Row S — /hyper:team ships the team-lead skill as rendered by claude-plugins,
# and nothing else. skills/team/ is generated by scripts/sync-team-skill.sh;
# this row checks the committed copy is a clean render (no template syntax,
# executable scripts, paths that point inside skills/team/), that it is in
# sync with the source checkout when one is present, and — against a fixture
# source, so it also runs in CI — that the sync script's --check really fails
# on every kind of drift.

source "$(dirname "${BASH_SOURCE[0]}")/helpers.sh"

sync="$SCRIPTS_DIR/sync-team-skill.sh"
team="$PLUGIN_DIR/skills/team"
scripts=(check-deps.sh rebase-worktrees.sh retire-agent.sh stall-watch.sh team-status.sh)
header="<!-- Generated from /work/claude-plugins/src/plugins/team-lead by agent-plugin/scripts/sync-team-skill.sh; do not edit here. -->"

# --- the committed copy --------------------------------------------------------

assert_ok "sync-team-skill.sh is executable" test -x "$sync"
assert_ok "skills/team/SKILL.md exists" test -f "$team/SKILL.md"
assert_ok "skills/team/default-models.yaml exists" test -f "$team/default-models.yaml"

leftover="$(grep -nE '\{\{|^@(if|else|elseif|end|let|each)\b' "$team/SKILL.md" || true)"
assert_eq "SKILL.md has no leftover template syntax" "" "$leftover"
# The plugin lists a skill by its directory, so the frontmatter name must
# match it: skills/team/ is /hyper:team, and /hyper:team-lead is the command.
assert_eq "SKILL.md frontmatter names the skill team (its directory)" \
  "team" "$(sed -n '2s/^name: *//p' "$team/SKILL.md")"
assert_fails "no commands/team.md shadows the skill" test -e "$PLUGIN_DIR/commands/team.md"
assert_eq "the generated-file header follows the frontmatter" \
  "$header" "$(awk 'f && NF { print; exit } /^---$/ && NR > 1 { f = 1 }' "$team/SKILL.md")"
assert_eq "no path still points at skills/team-lead/" \
  "0" "$(grep -c '/skills/team-lead/' "$team/SKILL.md")"
assert_eq "plugin-root paths use \${CLAUDE_PLUGIN_ROOT}" \
  "0" "$(grep -cE '\$CLAUDE_PLUGIN_ROOT|\{\{ *platform' "$team/SKILL.md")"
# Every ${CLAUDE_PLUGIN_ROOT}/skills/team/... file the skill tells the agent to
# run or read must exist in this plugin.
missing=""
while read -r rel; do
  [[ -n "$rel" ]] || continue
  [[ -e "$PLUGIN_DIR/$rel" ]] || missing="$missing $rel"
done < <(grep -oE '\$\{CLAUDE_PLUGIN_ROOT\}/skills/team/[A-Za-z0-9._/-]+' "$team/SKILL.md" \
  | sed 's|^${CLAUDE_PLUGIN_ROOT}/||' | sort -u)
assert_eq "every skills/team/ path in SKILL.md exists" "" "$missing"
for s in "${scripts[@]}"; do
  assert_ok "scripts/$s is executable" test -x "$team/scripts/$s"
done
assert_eq "skills/team/scripts holds exactly the five scripts" \
  "${scripts[*]}" "$(cd "$team/scripts" && ls | tr '\n' ' ' | sed 's/ $//')"

cmd_text="$(cat "$PLUGIN_DIR/commands/team-lead.md")"
assert_eq "commands/team-lead.md is named team-lead" \
  "team-lead" "$(sed -n '2s/^name: *//p' "$PLUGIN_DIR/commands/team-lead.md")"
assert_contains "commands/team-lead.md invokes the team skill" "$cmd_text" "**team** skill"
assert_contains "commands/team-lead.md keeps the team-lead data dir" "$cmd_text" "hyper/team-lead/harnesses.yaml"

# In sync with the real source, when this machine has it. CI does not, so the
# fixture section below is what proves --check works there.
real_source="${TEAM_LEAD_SOURCE:-/work/claude-plugins}"
if [[ -f "$real_source/dist/claude/plugins/team-lead/skills/team-lead/SKILL.md" ]]; then
  assert_ok "skills/team is in sync with $real_source (sync-team-skill.sh --check)" \
    bash "$sync" --check --source "$real_source"
else
  skip "skills/team is in sync with the claude-plugins source" "no checkout at $real_source"
fi

# --- the sync script, against a fixture source -------------------------------

plugin="$FIX/plugin"
mkdir -p "$plugin/scripts"
cp "$sync" "$plugin/scripts/sync-team-skill.sh"
fsync="$plugin/scripts/sync-team-skill.sh"
src="$FIX/claude-plugins"
dist="$src/dist/claude/plugins/team-lead/skills/team-lead"
mkdir -p "$dist/scripts"
cat > "$dist/SKILL.md" <<'EOF'
---
name: team-lead
description: fixture
---

# Team Lead

Run {{ platform.pluginRootVar }}/skills/team-lead/scripts/check-deps.sh first.
Then read `$CLAUDE_PLUGIN_ROOT/skills/team-lead/default-models.yaml`.
Leave $CLAUDE_PLUGIN_ROOT_EXTRA alone.
Config: `${XDG_CONFIG_HOME:-$HOME/.config}/hyper/team-lead/harnesses.yaml`.
EOF
echo "routing: {}" > "$dist/default-models.yaml"
# --check runs `bun run build:check` in the source; the fixture's answer is
# whatever this script says (fresh unless a test flips it).
printf '{"scripts":{"build:check":"sh ./fresh.sh"}}\n' > "$src/package.json"
echo 'exit 0' > "$src/fresh.sh"
echo "upstream notes" > "$dist/TODO.md"
for s in "${scripts[@]}"; do
  printf '#!/usr/bin/env bash\necho %s\n' "$s" > "$dist/scripts/$s"
  chmod 755 "$dist/scripts/$s"
done
out="$plugin/skills/team"

assert_fails "--check fails before the first sync" bash "$fsync" --check --source "$src"
assert_ok "sync succeeds" bash "$fsync" --source "$src"
assert_ok "--check passes right after a sync" bash "$fsync" --check --source "$src"

synced="$(cat "$out/SKILL.md")"
assert_eq "frontmatter stays first" "---" "$(head -1 "$out/SKILL.md")"
assert_eq "frontmatter name becomes team" "name: team" "$(sed -n 2p "$out/SKILL.md")"
assert_eq "header is the first line after the frontmatter" "$header" "$(sed -n 6p "$out/SKILL.md")"
assert_contains "unrendered root var is rewritten" "$synced" \
  'Run ${CLAUDE_PLUGIN_ROOT}/skills/team/scripts/check-deps.sh first.'
assert_contains "bare \$CLAUDE_PLUGIN_ROOT is braced and repointed" "$synced" \
  '`${CLAUDE_PLUGIN_ROOT}/skills/team/default-models.yaml`'
assert_contains "the team-lead data dir is left alone" "$synced" "hyper/team-lead/harnesses.yaml"
assert_contains "a longer variable that starts with CLAUDE_PLUGIN_ROOT is left alone" "$synced" \
  'Leave $CLAUDE_PLUGIN_ROOT_EXTRA alone.'
assert_ok "default-models.yaml is copied byte for byte" cmp "$dist/default-models.yaml" "$out/default-models.yaml"
assert_fails "TODO.md is not shipped" test -e "$out/TODO.md"
for s in "${scripts[@]}"; do
  assert_ok "$s is byte-identical to the render" cmp "$dist/scripts/$s" "$out/scripts/$s"
  assert_ok "$s is executable" test -x "$out/scripts/$s"
done

# Every kind of drift fails --check: the source moving, a hand edit here, a
# lost executable bit, a stray file.
echo "new upstream line" >> "$dist/SKILL.md"
assert_fails "--check fails when the source SKILL.md changes" bash "$fsync" --check --source "$src"
bash "$fsync" --source "$src" >/dev/null 2>&1
echo "# local edit" >> "$out/scripts/team-status.sh"
assert_fails "--check fails on a hand-edited script" bash "$fsync" --check --source "$src"
bash "$fsync" --source "$src" >/dev/null 2>&1
chmod -x "$out/scripts/stall-watch.sh"
assert_fails "--check fails when a script loses its executable bit" bash "$fsync" --check --source "$src"
bash "$fsync" --source "$src" >/dev/null 2>&1
touch "$out/scripts/extra.sh"
assert_fails "--check fails on a file the source does not have" bash "$fsync" --check --source "$src"
bash "$fsync" --source "$src" >/dev/null 2>&1
assert_ok "a re-sync clears every drift" bash "$fsync" --check --source "$src"

# A stale dist/ must not pass --check just because skills/team matches it.
echo 'exit 1' > "$src/fresh.sh"
stale_out="$(bash "$fsync" --check --source "$src" 2>&1)"; stale_rc=$?
assert_eq "--check fails when the source dist is stale" "1" "$stale_rc"
assert_contains "--check says dist is stale" "$stale_out" "dist is stale"
echo 'exit 0' > "$src/fresh.sh"

# --check is write-nothing; --build rewrites the source's dist/.
bash "$fsync" --check --build --source "$src" >/dev/null 2>&1; both_rc=$?
assert_eq "--check --build is refused with exit 2" "2" "$both_rc"

# Each broken render is refused, and a refused sync leaves the committed copy
# untouched. The clean source SKILL.md is restored between cases so each one
# fails for its own reason only.
cp "$dist/SKILL.md" "$FIX/skill.bak"
before="$(cat "$out/SKILL.md")"

{ cat "$FIX/skill.bak"; printf '@if(platform.contextInjection)\nx\n@end\n'; } > "$dist/SKILL.md"
assert_fails "sync refuses a SKILL.md with leftover template syntax" bash "$fsync" --source "$src"
assert_eq "a refused sync leaves skills/team untouched" "$before" "$(cat "$out/SKILL.md")"

{ echo "stray first line"; cat "$FIX/skill.bak"; } > "$dist/SKILL.md"
assert_fails "sync refuses a SKILL.md whose line 1 is not ---" bash "$fsync" --source "$src"

sed 's/^name: team-lead$/name: other/' "$FIX/skill.bak" > "$dist/SKILL.md"
assert_fails "sync refuses a SKILL.md without name: team-lead" bash "$fsync" --source "$src"

printf -- '---\nname: team-lead\nno closing fence\n' > "$dist/SKILL.md"
assert_fails "sync refuses a SKILL.md with unclosed frontmatter" bash "$fsync" --source "$src"

cp "$FIX/skill.bak" "$dist/SKILL.md"
assert_ok "the restored source syncs again" bash "$fsync" --source "$src"

rm "$dist/scripts/retire-agent.sh"
assert_fails "sync refuses a render missing one of the five scripts" bash "$fsync" --source "$src"
assert_ok "a refused sync keeps the shipped script" test -x "$out/scripts/retire-agent.sh"
assert_fails "an absent source is an error, not a silent no-op" bash "$fsync" --check --source "$FIX/nowhere"

finish
